{"tiddlers":{"$:/themes/huwiki/hupedia/style.css":{"title":"$:/themes/huwiki/hupedia/style.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* HUPedia 0.2.2: appearance only; article rendering belongs to the plugin. */
body.tc-body {
  --hupedia-border: #a2a9b1;
  --hupedia-surface: #f8f9fa;
  --hupedia-text: #202122;
  --hupedia-muted: #54595d;
  --hupedia-accent-soft: #dbe6f2;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  color: var(--hupedia-text);
  background: #f8f9fa;
}

.tc-sidebar-header {
  border-top: 5px solid #274b76;
  padding-top: 0.85rem;
}

.tc-site-title {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.7em;
  color: var(--hupedia-text);
}

.tc-site-subtitle {
  color: var(--hupedia-muted);
}

.tc-tiddler-frame {
  padding: 1.5rem 1.75rem;
  border: 1px solid #c8ccd1;
  border-radius: 0.2rem;
  background: #fff;
  box-shadow: none;
}

.tc-tiddler-title {
  border-bottom: 1px solid var(--hupedia-border);
  padding-bottom: 0.4rem;
  font-family: Georgia, "Times New Roman", serif;
}

.tc-tiddler-body {
  color: var(--hupedia-text);
  font-size: 1.02em;
  line-height: 1.65;
}

.tc-tiddler-body h2 {
  margin-top: 1.6em;
  border-bottom: 1px solid var(--hupedia-border);
  font-family: Georgia, serif;
  font-size: 1.55em;
}

.tc-tiddler-body h3 {
  font-family: Georgia, serif;
  font-size: 1.25em;
}

.tc-tiddler-body a,
.hupedia-sidebar a {
  color: #365fa0;
}

.hupedia-welcome {
  margin-bottom: 1rem;
  padding: 1rem 1.2rem;
  border-left: 4px solid #315a88;
  background: #f5f8fd;
}

.hupedia-eyebrow {
  color: var(--hupedia-muted);
  font-size: 0.75em;
  font-weight: bold;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.hupedia-quicklinks {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin: 1rem 0;
}

.hupedia-quicklinks a {
  padding: 0.45rem 0.65rem;
  border: 1px solid #c9d6e9;
  border-radius: 0.25rem;
  background: #eef2f8;
}

.hupedia-panel {
  margin: 0.75rem 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--hupedia-border);
  background: var(--hupedia-surface);
}

.hupedia-panel h3 {
  margin: 0 0 0.65rem;
  font-size: 1.1em;
}

.hupedia-sidebar .hupedia-articlelink {
  padding: 0.35rem 0.2rem;
  border-bottom: 1px solid #eaecf0;
}

.hupedia-new {
  padding: 0.6rem 0.85rem;
  border: 0;
  border-radius: 0.25rem;
  background: #315a88;
  color: #fff;
  font-weight: 600;
}

@media (max-width: 900px) {
  .tc-tiddler-frame {
    padding: 1rem;
  }
}
"},"$:/themes/huwiki/hupedia/sidebar":{"title":"$:/themes/huwiki/hupedia/sidebar","tags":"$:/tags/SideBar","caption":"HUPedia","type":"text/vnd.tiddlywiki","text":"\whitespace trim

