<div class="hupedia-sidebar">
  <h3>HUPedia</h3>
  <p>
    <$link to="HUPedia · Start">Forside</$link>
    · <$link to="HUPedia · Redaktion">Redaktion</$link>
  </p>
  <p>
    <$button class="hupedia-new">
      <$action-sendmessage
        $message="tm-new-tiddler"
        tags="HUPedia/Artikel"
        pedia-status="kladde"
      />
      + Ny artikel
    </$button>
  </p>
  <h4>Artikler A–Å</h4>
  <$list
    filter="
      [all[tiddlers]tag[HUPedia/Artikel]]
      [all[tiddlers]tag[HUPedia/Article]]
      [all[tiddlers]tag[HUPedia/Person]]
      [all[tiddlers]tag[HUPedia/Sted]]
      [all[tiddlers]tag[HUPedia/Place]]
      [all[tiddlers]tag[HUPedia/Begivenhed]]
      [all[tiddlers]tag[HUPedia/Event]]
      [all[tiddlers]tag[HUPedia/Organisation]]
      [all[tiddlers]tag[HUPedia/Organization]]
      [all[tiddlers]tag[HUPedia/Musikværk]]
      [all[tiddlers]tag[HUPedia/MusicalWork]]
      [all[tiddlers]tag[HUPedia/Begreb]]
      [all[tiddlers]tag[HUPedia/Concept]]
      [all[tiddlers]tag[PediaArtikel]]
      +[!is[system]!is[draft]unique[]sort[title]]
    "
    emptyMessage="Ingen artikler endnu."
  >
    <div class="hupedia-articlelink"><$link/></div>
  </$list>
</div>
